create table if not exists public.occurrences(id bigint generated by default as identity primary key,number integer not null,title text not null,category text default 'Outros',status text default 'Em análise',priority text default 'Média',date date,time time,location text,involved text,description text,actions text,responsible text,protocol text,attachments jsonb default '[]'::jsonb,attachment_count integer default 0,created_at timestamptz default now(),updated_at timestamptz default now());
alter table public.occurrences enable row level security;
drop policy if exists "Resumo publico ocorrencias" on public.occurrences;drop policy if exists "Admin gerencia ocorrencias" on public.occurrences;
create policy "Resumo publico ocorrencias" on public.occurrences for select to anon,authenticated using(true);
create policy "Admin gerencia ocorrencias" on public.occurrences for all to authenticated using(true) with check(true);
